/bin/bash -lc "python3 - <<'PY'
import ast, copy, hashlib, importlib.util, json
from pathlib import Path
r=json.load(open('runtime_context.json'));p=json.load(open('proposal.json'))
schema=r['study_schema']
def validate(x,s,path='study'):
 t=s.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool}
 if t: assert isinstance(x,types[t]),(path,t)
 if 'const' in s: assert x==s['const'],path
 if 'enum' in s: assert x in s['enum'],path
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'missing')
  if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):validate(v,s.get('items',{}),path+f'[{i}]')
 if isinstance(x,str):assert len(x)>=s.get('minLength',0),path
validate(p['study'],schema)
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert len({v['file'] for v in p['variants']})==4
assert len({v['name'] for v in p['variants']})==4
assert any(v['role']=='candidate' for v in p['variants'])
canonical=[]
for v in p['variants']:
 file=Path(v['file']);assert file.name==str(file) and file.suffix=='.py'
 source=file.read_text();compile(source,str(file),'exec');tree=ast.parse(source)
 cfg_nodes=[n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)]
 assert len(cfg_nodes)==1
 assert ast.literal_eval(cfg_nodes[0].value)==v['config']
 for node in ast.walk(tree):
  if isinstance(node,(ast.Import,ast.ImportFrom)):
   roots=[node.module.split('.')[0]] if isinstance(node,ast.ImportFrom) else [n.name.split('.')[0] for n in node.names]
   assert set(roots)<={'torch','unirank'},roots
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):assert node.func.id not in {'open','eval','exec','__import__','input'}
 tree.body.remove(cfg_nodes[0]);canonical.append(ast.dump(tree,include_attributes=False))
 assert hashlib.sha256(source.encode()).hexdigest() in v['note']
assert len(set(canonical))==1,'Factorial variants must differ only in CONFIG'
baseline=hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()
assert baseline=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
for file,digest in [('history_g1_r0004_field_d1_q0.py','78e0b3d5d78c3192d270a8196bb76010f065213520343ba9c676cf3a0a4aec67')]:
 assert hashlib.sha256(Path(file).read_bytes()).hexdigest()==digest
expected={a['knowledge_id'] for a in r['context']['latest_knowledge_usage']['assessments']}
expected|={'unirank-method-hyformer'}
assert expected<={a['knowledge_id'] for a in p['knowledge_assessments']}
for a in p['knowledge_assessments']:
 assert set(a['variant_names'])<={v['name'] for v in p['variants']}
 assert a['decision'] in {'used','considered','rejected','unresolved'}
print('PASS: study schema, protocol and evidence IDs; four standalone model syntax/ASTs; allowed imports; CONFIG consistency; variants differ only in CONFIG; hashes; frozen baseline/parent; source assessment coverage.')
print('PyTorch available:',importlib.util.find_spec('torch') is not None)
for v in p['variants']:print(v['name'],v['file'],v['role'])
PY"

